                        if (c < '0' || c > '9') {
                            allDigits = false;
                            break;
                        }
                    }

                    if (!allDigits) {
                        clazz = config.checkAutoType(typeName, null, lexer.getFeatures());
                    }
                }

                if (clazz == null) {
                    object.put(JSON.DEFAULT_TYPE_KEY, typeName);
                    continue;
                }

                lexer.nextToken(JSONToken.COMMA);
